from itertools import permutations

class Solution:
    def nextPalindrome(self, num: str) -> str:
        best = None
        for p in set(permutations(num)):
            cand = ''.join(p)
            if cand > num and cand == cand[::-1] and (best is None or cand < best):
                best = cand
        return best or ""

