import java.util.*;

class Solution {
    public String nextPalindrome(String num) {
        char[] a = num.toCharArray();
        Arrays.sort(a);
        Set<String> seen = new HashSet<>();
        List<String> perms = new ArrayList<>();
        permute(a, new boolean[a.length()], new StringBuilder(), seen, perms);
        String best = null;
        for (String cand : perms)
            if (cand.compareTo(num) > 0 && cand.equals(new StringBuilder(cand).reverse().toString()))
                if (best == null || cand.compareTo(best) < 0) best = cand;
        return best == null ? "" : best;
    }

    private void permute(char[] a, boolean[] used, StringBuilder cur, Set<String> seen, List<String> out) {
        if (cur.length() == a.length()) {
            String s = cur.toString();
            if (seen.add(s)) out.add(s);
            return;
        }
        for (int i = 0; i < a.length; i++) {
            if (used[i]) continue;
            used[i] = true;
            cur.append(a[i]);
            permute(a, used, cur, seen, out);
            cur.deleteCharAt(cur.length() - 1);
            used[i] = false;
        }
    }
}

