var nextPalindrome = function(num) {
    const chars = num.split('').sort();
    const seen = new Set();
    let best = null;
    const permute = (arr, used) => {
        if (arr.length === chars.length) {
            const cand = arr.join('');
            if (!seen.has(cand)) {
                seen.add(cand);
                const rev = cand.split('').reverse().join('');
                if (cand > num && cand === rev && (best === null || cand < best)) best = cand;
            }
            return;
        }
        for (let i = 0; i < chars.length; i++) {
            if (used[i]) continue;
            used[i] = true;
            arr.push(chars[i]);
            permute(arr, used);
            arr.pop();
            used[i] = false;
        }
    };
    permute([], new Array(chars.length).fill(false));
    return best || '';
};

