class Solution {
public:
    string nextPalindrome(string num) {
        int n = num.size();
        int k = n / 2;
        string left = num.substr(0, k);
        int i = k - 2;
        while (i >= 0 && left[i] >= left[i + 1]) i--;
        if (i < 0) return "";
        int j = k - 1;
        while (left[j] <= left[i]) j--;
        swap(left[i], left[j]);
        reverse(left.begin() + i + 1, left.end());
        string rev(left.rbegin(), left.rend());
        string mid = (n % 2 == 1) ? string(1, num[k]) : "";
        return left + mid + rev;
    }
};

