class Solution {
    public String nextPalindrome(String num) {
        int n = num.length();
        int k = n / 2;
        char[] left = num.substring(0, k).toCharArray();
        int i = k - 2;
        while (i >= 0 && left[i] >= left[i + 1]) i--;
        if (i < 0) return "";
        int j = k - 1;
        while (left[j] <= left[i]) j--;
        char tmp = left[i];
        left[i] = left[j];
        left[j] = tmp;
        for (int l = i + 1, r = k - 1; l < r; l++, r--) {
            char c = left[l];
            left[l] = left[r];
            left[r] = c;
        }
        String head = new String(left);
        String mid = (n % 2 == 1) ? String.valueOf(num.charAt(k)) : "";
        String rev = new StringBuilder(head).reverse().toString();
        return head + mid + rev;
    }
}

