var nextPalindrome = function(num) {
    const n = num.length;
    const k = n >> 1;
    const left = num.slice(0, k).split('');
    let i = k - 2;
    while (i >= 0 && left[i] >= left[i + 1]) i--;
    if (i < 0) return '';
    let j = k - 1;
    while (left[j] <= left[i]) j--;
    [left[i], left[j]] = [left[j], left[i]];
    const suffix = left.slice(i + 1).reverse();
    left.length = i + 1;
    left.push(...suffix);
    const head = left.join('');
    const mid = n % 2 === 1 ? num[k] : '';
    return head + mid + head.split('').reverse().join('');
};
